class Solution:
    def solve(self, spec_path: str = None) -> dict:
        code = r'''
import networkx as nx
from collections import defaultdict
import random
import math
import heapq

class BroadCastTopology:
    def __init__(self, src: str, dsts: list, num_partitions: int):
        self.src = src
        self.dsts = dsts
        self.num_partitions = int(num_partitions)
        self.paths = {dst: {str(i): None for i in range(self.num_partitions)} for dst in dsts}

    def append_dst_partition_path(self, dst: str, partition: int, path: list):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

    def set_dst_partition_paths(self, dst: str, partition: int, paths: list):
        partition = str(partition)
        self.paths[dst][partition] = paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions


def search_algorithm(src, dsts, G, num_partitions):
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    num_vms = 2
    instance_rate = 0.54  # $/hour

    # Try to get data_vol from graph attributes
    data_vol = 300.0  # default from problem description
    if hasattr(G, 'graph') and 'data_vol' in G.graph:
        data_vol = float(G.graph['data_vol'])

    partition_size = data_vol / num_partitions  # GB per partition

    ingress_limits = {"aws": 10, "gcp": 16, "azure": 16}
    egress_limits = {"aws": 5, "gcp": 7, "azure": 16}

    def get_provider(node):
        return node.split(":")[0]

    def node_egress_bw(node):
        return egress_limits.get(get_provider(node), 5) * num_vms

    def node_ingress_bw(node):
        return ingress_limits.get(get_provider(node), 10) * num_vms

    def path_edges(path):
        edges = []
        for i in range(len(path) - 1):
            edges.append([path[i], path[i+1], dict(G[path[i]][path[i+1]])])
        return edges

    # Generate candidate paths for each destination
    K_PATHS = 15
    dst_paths = {}
    for dst in dsts:
        paths = []
        try:
            gen = nx.shortest_simple_paths(G, src, dst, weight="cost")
            for i, p in enumerate(gen):
                if i >= K_PATHS:
                    break
                paths.append(p)
        except:
            pass
        # Also add shortest hop path
        try:
            sp = nx.shortest_path(G, src, dst)
            if sp not in paths:
                paths.append(sp)
        except:
            pass
        # Add path optimized for throughput (use -log(throughput) as weight)
        try:
            inv_tp_G = nx.DiGraph()
            for u, v, d in G.edges(data=True):
                tp = d.get("throughput", 0.001)
                inv_tp_G.add_edge(u, v, weight=1.0/max(tp, 0.001))
            tp_path = nx.shortest_path(inv_tp_G, src, dst, weight="weight")
            if tp_path not in paths:
                paths.append(tp_path)
        except:
            pass
        dst_paths[dst] = paths

    class CostModel:
        """Accurately model the evaluator's cost function."""
        def __init__(self):
            self.edge_partitions = defaultdict(int)  # (u,v) -> count of partitions
            self.node_out_edges = defaultdict(set)  # node -> set of (u,v) edges going out
            self.node_in_edges = defaultdict(set)   # node -> set of (u,v) edges coming in
            self.nodes_used = set()

        def add_path(self, path):
            """Add a partition using this path."""
            for i in range(len(path) - 1):
                u, v = path[i], path[i+1]
                ek = (u, v)
                self.edge_partitions[ek] += 1
                self.node_out_edges[u].add(ek)
                self.node_in_edges[v].add(ek)
                self.nodes_used.add(u)
                self.nodes_used.add(v)

        def remove_path(self, path):
            """Remove a partition from this path."""
            for i in range(len(path) - 1):
                u, v = path[i], path[i+1]
                ek = (u, v)
                self.edge_partitions[ek] -= 1
                if self.edge_partitions[ek] <= 0:
                    del self.edge_partitions[ek]
                    self.node_out_edges[u].discard(ek)
                    self.node_in_edges[v].discard(ek)
            # Recompute nodes_used
            self.nodes_used = set()
            for ek in self.edge_partitions:
                self.nodes_used.add(ek[0])
                self.nodes_used.add(ek[1])

        def compute_cost(self):
            if not self.edge_partitions:
                return float('inf'), 0, 0, 0

            # Egress cost
            egress_cost = 0.0
            for (u, v), count in self.edge_partitions.items():
                cost_per_gb = G[u][v].get("cost", 0.0)
                egress_cost += count * partition_size * cost_per_gb

            # Transfer time: max over all edges of (partitions * partition_size * 8 / actual_bw)
            max_transfer_time = 0.0
            for (u, v), count in self.edge_partitions.items():
                edge_tp = G[u][v].get("throughput", 0.001)
                n_out = len(self.node_out_edges[u])
                eg_bw = node_egress_bw(u) / max(n_out, 1)
                n_in = len(self.node_in_edges[v])
                ig_bw = node_ingress_bw(v) / max(n_in, 1)
                actual_bw = min(edge_tp, eg_bw, ig_bw)
                if actual_bw <= 0:
                    actual_bw = 0.001
                tt = count * partition_size * 8.0 / actual_bw
                if tt > max_transfer_time:
                    max_transfer_time = tt

            # Instance cost = |V| * n_vm * (r_instance / 3600) * t_transfer
            inst_cost = len(self.nodes_used) * num_vms * (instance_rate / 3600.0) * max_transfer_time

            total = egress_cost + inst_cost
            return total, egress_cost, inst_cost, max_transfer_time

        def clone(self):
            c = CostModel()
            c.edge_partitions = defaultdict(int, self.edge_partitions)
            c.node_out_edges = defaultdict(set)
            for k, v in self.node_out_edges.items():
                c.node_out_edges[k] = set(v)
            c.node_in_edges = defaultdict(set)
            for k, v in self.node_in_edges.items():
                c.node_in_edges[k] = set(v)
            c.nodes_used = set(self.nodes_used)
            return c

    # ================================================================
    # Strategy 1: All partitions on cheapest path (baseline)
    # ================================================================
    def make_assignment_all_cheapest():
        assignment = {}
        for dst in dsts:
            if not dst_paths[dst]:
                continue
            for p in range(num_partitions):
                assignment[(dst, p)] = 0
        return assignment

    def eval_assignment(assignment):
        model = CostModel()
        for (dst, p), idx in assignment.items():
            paths = dst_paths.get(dst, [])
            if idx < len(paths):
                model.add_path(paths[idx])
        return model.compute_cost()[0]

    # ================================================================
    # Strategy 2: Greedy assignment - add partitions one by one, pick 
    # path that minimizes total cost increase
    # ================================================================
    def strategy_greedy():
        model = CostModel()
        assignment = {}

        # Order: interleave destinations so load is balanced
        items = []
        for p in range(num_partitions):
            for dst in dsts:
                items.append((dst, p))

        for dst, p in items:
            paths = dst_paths.get(dst, [])
            if not paths:
                continue

            best_idx = 0
            best_cost = float('inf')

            for idx, path in enumerate(paths):
                # Temporarily add
                model.add_path(path)
                cost = model.compute_cost()[0]
                model.remove_path(path)

                if cost < best_cost:
                    best_cost = cost
                    best_idx = idx

            assignment[(dst, p)] = best_idx
            model.add_path(paths[best_idx])

        return assignment

    # ================================================================
    # Strategy 3: Spread partitions across paths evenly
    # ================================================================
    def strategy_spread():
        assignment = {}
        for dst in dsts:
            paths = dst_paths.get(dst, [])
            if not paths:
                continue
            n_use = min(len(paths), max(2, num_partitions // 2))
            for p in range(num_partitions):
                assignment[(dst, p)] = p % n_use
        return assignment

    # ================================================================
    # Strategy 4: Steiner tree - minimize node count and edge reuse
    # ================================================================
    def strategy_steiner():
        assignment = {}
        tree_nodes = {src}
        tree_edges_set = set()
        dst_full_paths = {}

        remaining = list(dsts)

        while remaining:
            best_dst = None
            best_path = None
            best_new_cost = float('inf')

            for dst in remaining:
                for tn in list(tree_nodes):
                    try:
                        path = nx.shortest_path(G, tn, dst, weight="cost")
                        # Cost = new edges cost + new nodes count penalty
                        new_edge_cost = 0
                        new_nodes = 0
                        for i in range(len(path)-1):
                            ec = G[path[i]][path[i+1]].get("cost", 0)
                            if (path[i], path[i+1]) not in tree_edges_set:
                                new_edge_cost += ec
                        for n in path:
                            if n not in tree_nodes:
                                new_nodes += 1
                        score = new_edge_cost * partition_size * num_partitions + new_nodes * num_vms * instance_rate * 0.01
                        if score < best_new_cost:
                            best_new_cost = score
                            best_path = path
                            best_dst = dst
                    except:
                        pass

            if best_dst is None:
                break

            remaining.remove(best_dst)
            for n in best_path:
                tree_nodes.add(n)
            for i in range(len(best_path)-1):
                tree_edges_set.add((best_path[i], best_path[i+1]))

            try:
                tree_G = nx.DiGraph()
                for u, v in tree_edges_set:
                    tree_G.add_edge(u, v, **G[u][v])
                full_path = nx.shortest_path(tree_G, src, best_dst, weight="cost")
                dst_full_paths[best_dst] = full_path
            except:
                cands = dst_paths.get(best_dst, [])
                if cands:
                    dst_full_paths[best_dst] = cands[0]

        for dst in dsts:
            if dst in dst_full_paths:
                path = dst_full_paths[dst]
                cands = dst_paths[dst]
                idx = None
                for i, c in enumerate(cands):
                    if c == path:
                        idx = i
                        break
                if idx is None:
                    cands.append(path)
                    idx = len(cands) - 1
                for p in range(num_partitions):
                    assignment[(dst, p)] = idx
            else:
                cands = dst_paths.get(dst, [])
                if cands:
                    for p in range(num_partitions):
                        assignment[(dst, p)] = 0

        return assignment

    # ================================================================
    # Strategy 5: Two-phase - cheapest single path but vary per dst
    # ================================================================
    def strategy_best_single_path():
        """For each destination, try all candidate paths (all partitions on same path), pick cheapest combo."""
        # This is a combinatorial problem over destinations
        # Use greedy: for each dst, pick the path that minimizes marginal cost
        model = CostModel()
        assignment = {}

        for dst in dsts:
            paths = dst_paths.get(dst, [])
            if not paths:
                continue

            best_idx = 0
            best_cost = float('inf')

            for idx, path in enumerate(paths):
                # Add all partitions on this path temporarily
                for _ in range(num_partitions):
                    model.add_path(path)
                cost = model.compute_cost()[0]
                for _ in range(num_partitions):
                    model.remove_path(path)

                if cost < best_cost:
                    best_cost = cost
                    best_idx = idx

            chosen = paths[best_idx]
            for p in range(num_partitions):
                assignment[(dst, p)] = best_idx
                model.add_path(chosen)

        return assignment

    # ================================================================
    # Evaluate all strategies
    # ================================================================
    strategies = {
        "cheapest": make_assignment_all_cheapest,
        "greedy": strategy_greedy,
        "spread": strategy_spread,
        "steiner": strategy_steiner,
        "best_single": strategy_best_single_path,
    }

    best_assignment = None
    best_cost = float('inf')
    best_name = ""

    for name, fn in strategies.items():
        try:
            a = fn()
            c = eval_assignment(a)
            if c < best_cost:
                best_cost = c
                best_assignment = a
                best_name = name
        except Exception as e:
            pass

    if best_assignment is None:
        best_assignment = make_assignment_all_cheapest()
        best_cost = eval_assignment(best_assignment)

    # ================================================================
    # Local search: iteratively try to improve by changing one 
    # (dst, partition) assignment at a time
    # ================================================================
    improved = True
    max_rounds = 5
    round_num = 0
    while improved and round_num < max_rounds:
        improved = False
        round_num += 1
        for dst in dsts:
            paths = dst_paths.get(dst, [])
            if not paths or len(paths) <= 1:
                continue
            for p in range(num_partitions):
                key = (dst, p)
                current_idx = best_assignment.get(key, 0)

                for new_idx in range(len(paths)):
                    if new_idx == current_idx:
                        continue

                    old_assignment = dict(best_assignment)
                    old_assignment[key] = new_idx
                    new_cost = eval_assignment(old_assignment)

                    if new_cost < best_cost - 1e-9:
                        best_cost = new_cost
                        best_assignment = old_assignment
                        improved = True

    # ================================================================  
    # Simulated annealing for further improvement
    # ================================================================
    random.seed(42)
    current_assignment = dict(best_assignment)
    current_cost = best_cost
    sa_best_assignment = dict(best_assignment)
    sa_best_cost = best_cost

    temperature = max(best_cost * 0.05, 1.0)
    cooling = 0.997

    all_keys = [(dst, p) for dst in dsts for p in range(num_partitions)]
    n_iters = min(5000, len(all_keys) * 20)

    for it in range(n_iters):
        key = random.choice(all_keys)
        dst, p = key
        paths = dst_paths.get(dst, [])
        if not paths or len(paths) <= 1:
            continue

        cur_idx = current_assignment.get(key, 0)
        new_idx = random.randint(0, len(paths) - 1)
        if new_idx == cur_idx:
            continue

        test = dict(current_assignment)
        test[key] = new_idx
        test_cost = eval_assignment(test)

        delta = test_cost - current_cost
        if delta < 0 or (temperature > 0 and random.random() < math.exp(-delta / max(temperature, 1e-10))):
            current_assignment = test
            current_cost = test_cost
            if current_cost < sa_best_cost:
                sa_best_cost = current_cost
                sa_best_assignment = dict(current_assignment)

        temperature *= cooling

    if sa_best_cost < best_cost:
        best_assignment = sa_best_assignment
        best_cost = sa_best_cost

    # ================================================================
    # Try swapping multiple partitions for a destination at once
    # ================================================================
    for dst in dsts:
        paths = dst_paths.get(dst, [])
        if not paths:
            continue
        for target_idx in range(len(paths)):
            test = dict(best_assignment)
            for p in range(num_partitions):
                test[(dst, p)] = target_idx
            tc = eval_assignment(test)
            if tc < best_cost:
                best_cost = tc
                best_assignment = test

    # ================================================================
    # Build final topology
    # ================================================================
    for dst in dsts:
        paths_list = dst_paths.get(dst, [])
        if not paths_list:
            continue
        for p in range(num_partitions):
            key = (dst, p)
            idx = best_assignment.get(key, 0)
            if idx >= len(paths_list):
                idx = 0
            path = paths_list[idx]
            edges = path_edges(path)
            bc_topology.set_dst_partition_paths(dst, p, edges)

    return bc_topology
